create table if not exists tka_results (result_id uuid primary key, attempt_id uuid not null unique references tka_attempts(attempt_id), student_id uuid not null references student_identities(student_id), exam_id uuid not null references tka_exams(exam_id), session_id uuid not null references tka_sessions(session_id), subject_id text not null, raw_score numeric not null, scaled_score numeric not null check(scaled_score between 0 and 100), score_scale text not null, achievement_category text not null, finalized_at timestamptz not null default now());
create table if not exists tka_events (event_id uuid primary key, event_type text not null, source_id uuid not null, payload jsonb not null, occurred_at timestamptz not null default now(), unique(event_type,source_id));
